<?php
require_once __DIR__.'/bootstrap/app.php';require_role('SUPER_ADMIN');$q=trim($_GET['q']??'');$rows=db_all("SELECT m.MemberID,m.MemberNumber,m.Name,m.NIC,m.Email,m.PhoneNo,u.Status AccountStatus,s.Status SubscriptionStatus,s.EndsAt,s.PlanNameSnapshot FROM MEMBER m LEFT JOIN USER_ACCOUNT u ON u.MemberID=m.MemberID LEFT JOIN SUBSCRIPTION s ON s.SubscriptionID=(SELECT s2.SubscriptionID FROM SUBSCRIPTION s2 WHERE s2.MemberID=m.MemberID ORDER BY s2.SubscriptionID DESC LIMIT 1) WHERE (?='' OR m.Name LIKE CONCAT('%',?,'%') OR m.MemberNumber LIKE CONCAT('%',?,'%') OR m.Email LIKE CONCAT('%',?,'%')) ORDER BY m.MemberID DESC LIMIT 250",'sssss',[$q,$q,$q,$q,$q]);$pageTitle='Members';$pageSubtitle='Member identities and subscription status';include ROOT_PATH.'/includes/header.php';?><form class="filter-bar" method="get"><label class="sr-only" for="q">Search members</label><input id="q" name="q" value="<?=e($q)?>" placeholder="Search name, number, or email"><button class="btn btn-ghost">Search</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">Member</th><th scope="col">Contact</th><th scope="col">Account</th><th scope="col">Membership</th><th scope="col">Ends</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['Name'])?></strong><br><small><?=e($r['MemberNumber'])?> · NIC <?=e($r['NIC'])?></small></td><td><?=e($r['Email']??'—')?><br><small><?=e($r['PhoneNo']??'—')?></small></td><td><span class="badge <?=$r['AccountStatus']==='ACTIVE'?'badge-green':'badge-amber'?>"><?=e($r['AccountStatus']??'LEGACY PROFILE')?></span></td><td><?=e($r['PlanNameSnapshot']??'No plan')?><br><small><?=e($r['SubscriptionStatus']??'—')?></small></td><td><?=e($r['EndsAt']?date('d M Y',strtotime($r['EndsAt'])):'—')?></td></tr><?php endforeach;?></tbody></table></div><?php include ROOT_PATH.'/includes/footer.php';?>
